  `moda` tinyint(1) NOT NULL COMMENT 'Modalidad',
  `farc` date NOT NULL COMMENT 'Fecha del Archivo',
  `usua` int NOT NULL COMMENT 'Usuario Responsable',
  KEY `credito_id` (`credito_id`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;
